import React from 'react';
import { Link } from 'react-router-dom';
import './home.css';

const Home = () => {
  return (
    <div className="home-container">

      {/* Hero Section (Main Welcome & Buttons) */}
      <div className="hero-section">
        <h1>MMD Anaalytics India Private Limited</h1>
        <p className="hero-subtitle">
          Professional Financial Solutions & Trading Services<br /><br />
          Trusted partner for financial services, business consulting, broking solutions and coal trading based in Ranchi, Jharkhand.
        </p>

        {/* --- ACTION BUTTONS SECTION --- */}
        <div className="action-buttons-grid">
          <ul>
           <li>🟢<a href="PASTE_DEMAT_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-primary">
            Open Demat Account</a></li> 

          <li>🟢<a href="PASTE_CONSULTATION_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-secondary">
            Request Consultation</a></li>

          <li><a href="PASTE_COAL_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-secondary">
            Coal Enquiry </a></li>

          <Link to="/contact-us" className="btn btn-outline">
            Contact Us
          </Link>
          </ul>
        </div>
        {/* ------------------------------- */}
      </div>

      {/* Core Values Section */}
      <div className="values-section">
        <h2>Our Core Values</h2>
        <ul className="values-list">
          <li>Integrity in financial reporting</li>
          <li>Excellence in coal transport</li>
          <li>Customer-first broking</li>
        </ul>
      </div>

    </div>
  );
};

export default Home;
